        dumped = item.model_dump(by_alias=True)
        allowed = {
            (model.model_fields[n].serialization_alias or model.model_fields[n].alias or n)
            for n in required | {keep}
        }
        assert set(dumped) <= allowed, f"{model.__name__} kept {set(dumped) - allowed}"


